package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.text.StrBuilder#contains(char)
 */
public class StrBuilder_contains_TriageGen1Test {

    @Test
    public void testContains_EmptyBuilder() {
        StrBuilder sb = new StrBuilder();
        assertFalse("Should return false for an empty builder", sb.contains('a'));
    }

    @Test
    public void testContains_CharExistsAtStart() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is at the start", sb.contains('a'));
    }

    @Test
    public void testContains_CharExistsInMiddle() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is in the middle", sb.contains('b'));
    }

    @Test
    public void testContains_CharExistsAtEnd() {
        StrBuilder sb = new StrBuilder("abc");
        assertTrue("Should return true when char is at the end", sb.contains('c'));
    }

    @Test
    public void testContains_CharDoesNotExist() {
        StrBuilder sb = new StrBuilder("abc");
        assertFalse("Should return false when char is not present", sb.contains('z'));
    }

    @Test
    public void testContains_CaseSensitivity() {
        StrBuilder sb = new StrBuilder("Abc");
        assertFalse("Should be case sensitive", sb.contains('a'));
        assertTrue("Should be case sensitive", sb.contains('A'));
    }

    @Test
    public void testContains_WithSpecialCharacters() {
        StrBuilder sb = new StrBuilder("!@# ");
        assertTrue("Should find special characters", sb.contains('!'));
        assertTrue("Should find space", sb.contains(' '));
        assertFalse("Should not find non-existent special character", sb.contains('$'));
    }

    @Test
    public void testContains_AfterClear() {
        StrBuilder sb = new StrBuilder("abc");
        sb.clear();
        assertFalse("Should return false after builder is cleared", sb.contains('a'));
    }

    @Test
    public void testContains_AfterDelete() {
        StrBuilder sb = new StrBuilder("abc");
        sb.delete(0, 1); // removes 'a'
        assertFalse("Should return false after character is deleted", sb.contains('a'));
        assertTrue("Should still find remaining characters", sb.contains('b'));
    }

    @Test
    public void testContains_LargeCapacity() {
        StrBuilder sb = new StrBuilder(100);
        sb.append("test");
        assertTrue(sb.contains('t'));
        assertFalse(sb.contains('z'));
    }
}
